import{_ as a,H as o,f as t,i as s}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"plan","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/plan.md","filePath":"ko/skills/plan.md"}'),l={name:"ko/skills/plan.md"};function d(c,e,n,i,p,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;plan&quot;">​</a></h1><p><code>plan</code> 스킬은 승인된 명세를 <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>의 실행 가능한 마일스톤 작업으로 분할합니다. 배경, 아키텍처, 근거를 반복하지 않고 명세서 경로만 참조합니다.</p><h2 id="롤링-웨이브-및-멀티-모듈-토폴로지" tabindex="-1">롤링 웨이브 및 멀티 모듈 토폴로지 <a class="header-anchor" href="#롤링-웨이브-및-멀티-모듈-토폴로지" aria-label="Permalink to &quot;롤링 웨이브 및 멀티 모듈 토폴로지&quot;">​</a></h2><ul><li><strong>롤링 웨이브(Rolling wave)</strong>: 명세가 <code>docs/ROADMAP.md</code>의 <code>milestone: MN</code>을 참조하면 해당 마일스톤만 상세 전개하고 나머지는 한 줄 스텁으로 남깁니다. <code>ship</code> 완료 후 다음 마일스톤을 확인해 전개하며, 목표가 본질적으로 바뀐 경우에만 <code>design</code>으로 돌아갑니다.</li><li><strong>멀티 모듈 토폴로지</strong>: <code>topology=multi-module</code>이 선언되면 <a href="./multi-module.html">멀티 모듈 프로토콜</a>을 읽고 Coordinator 워크스페이스 계획 상단에 모드 선언 블록(<code>topology: multi-module</code>, <code>change-set</code>, <code>coordinator</code>, <code>repos</code>, 모듈 계획 경로, 통합 작업)을 둡니다. 각 작업은 하나의 <code>repository:</code>와 하나의 <code>module:</code>만 소유하며, 「계약 → 소비자 → 로컬 수용 → 통합 → 의존성 순 커밋」 순으로 배치합니다.</li></ul><h2 id="마일스톤-작업-각-30-60분" tabindex="-1">마일스톤 작업 (각 30~60분) <a class="header-anchor" href="#마일스톤-작업-각-30-60분" aria-label="Permalink to &quot;마일스톤 작업 (각 30~60분)&quot;">​</a></h2><p>모든 작업은 제목이 아닌 체크박스(<code>- [ ] T&lt;n&gt;: &lt;이름&gt;</code>)로 작성합니다:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;한 줄 목표&gt;</span></span>
<span class="line"><span>files:      &lt;대상 경로&gt;</span></span>
<span class="line"><span>acceptance: &lt;실행 가능한 테스트, 명령어 또는 명시적 수동 검증 절차&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>공유 계약·상태·수용 기준이 닫혀 있고 쓰기 범위가 겹치지 않는 독립 작업에만 <code>[parallel] T3, T4, T5</code>를 표시합니다. 원자적 단계 전개는 <code>subagents</code> 배포 시점까지 지연합니다.</p><h2 id="인계-게이트" tabindex="-1">인계 게이트 <a class="header-anchor" href="#인계-게이트" aria-label="Permalink to &quot;인계 게이트&quot;">​</a></h2><p><code>&lt;gate&gt;</code><code>tdd</code> 또는 <code>subagents</code>에 인계하기 전에 <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>(멀티 모듈 작업 시 모든 모듈 계획 파일 포함)가 디스크에 존재하고 사용자 확인을 받아야 합니다. <code>&lt;/gate&gt;</code></p>`,10)])])}const u=a(l,[["render",d]]);export{h as __pageData,u as default};
